#include <bits/stdc++.h>
using namespace std;

struct Scan {
    deque<string> buffer;

    Scan() : buffer() {}

    template <typename T>
    T next() {
        while (true) {
            if (!buffer.empty()) {
                string token = buffer.front();
                buffer.pop_front();
                if constexpr (is_same_v<T, string>) {
                    return token;
                } else {
                    T value;
                    std::istringstream iss(token);
                    iss >> value;
                    return value;
                }
            }
            string line;
            if (!getline(cin, line)) {
                throw runtime_error("Fail to read");
            }
            buffer.clear();
            istringstream iss(line);
            string word;
            while (iss >> word) {
                buffer.push_back(word);
            }
        }
    }
};

bool is_prime(size_t x) {
    if (x < 2) return false;
    for (size_t i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            return false;
        }
    }
    return true;
}

size_t next_prime(size_t x) {
    size_t aux = x + 1;
    while (!is_prime(aux)) {
        ++aux;
    }
    return aux;
}

void _main() {
    Scan scan;
    size_t n = scan.next<size_t>();
    size_t m = scan.next<size_t>();
    bool result = next_prime(n) == m;
    cout << (result ? "YES" : "NO") << '\n';
}

int main() {
    thread t([] { _main(); });
    t.join();
    return 0;
}

